'use client'
import React, { useCallback, useId } from 'react'

import type { ColumnProps } from '../types.js'

import { PlusIcon } from '../../../../icons/Plus/index.js'
import { useTranslation } from '../../../../providers/Translation/index.js'
import { Button } from '../../../Button/index.js'
import { LoadMoreRow } from '../../../LoadMoreRow/index.js'
import { Spinner } from '../../../Spinner/index.js'
import { ColumnItem } from '../ColumnItem/index.js'
import './index.css'

const baseClass = 'hierarchy-column'

export const Column: React.FC<ColumnProps> = ({
  ancestorsWithSelections,
  canCreate,
  collectionLabel,
  disabled,
  disabledIds,
  expandedId,
  filterByCollection,
  hasNextPage,
  isLoading,
  items,
  onCreateNew,
  onExpand,
  onLoadMore,
  onSelect,
  parentId,
  parentTitle,
  pathToColumn,
  selectedIds,
  totalDocs,
}) => {
  const { t } = useTranslation()
  const titleID = useId()
  const createID = useId()

  const headerTitle = parentTitle || (parentId === null ? t('general:all') : '')

  const handleSelect = useCallback(
    ({ id }: { id: number | string }) => {
      const item = items.find((i) => i.id === id)
      const fullPath = item ? [...pathToColumn, { id: item.id, title: item.title }] : pathToColumn
      onSelect({ id, path: fullPath })
    },
    [items, onSelect, pathToColumn],
  )

  const handleCreateNew = useCallback(() => {
    onCreateNew({ parentId, path: pathToColumn })
  }, [onCreateNew, parentId, pathToColumn])

  return (
    <div className={baseClass}>
      <div className={`${baseClass}__header`}>
        <h3 className={`${baseClass}__header-title`} id={titleID}>
          {headerTitle}
        </h3>
        {canCreate && (
          <Button
            buttonStyle="ghost"
            className={`${baseClass}__add-button`}
            disabled={disabled}
            extraButtonProps={{ 'aria-labelledby': `${createID} ${titleID}` }}
            icon={<PlusIcon size={16} />}
            iconPosition="left"
            margin={false}
            onClick={handleCreateNew}
            size="medium"
          >
            <span id={createID}>{t('general:newLabel', { label: collectionLabel })}</span>
          </Button>
        )}
      </div>

      <div className={`${baseClass}__items`}>
        {items.map((item) => (
          <ColumnItem
            disabled={Boolean(disabled || disabledIds?.has(item.id))}
            filterByCollection={filterByCollection}
            hasSelectedDescendants={ancestorsWithSelections.has(item.id)}
            isExpanded={expandedId === item.id}
            isSelected={selectedIds.has(item.id)}
            item={item}
            key={String(item.id)}
            onExpand={onExpand}
            onSelect={handleSelect}
          />
        ))}

        {isLoading && (
          <div className={`${baseClass}__loading`}>
            <Spinner loadingText={null} size="sm" />
          </div>
        )}

        {!disabled && !isLoading && totalDocs > 0 && (
          <LoadMoreRow
            className={`${baseClass}__load-more`}
            currentCount={items.length}
            hasMore={hasNextPage}
            onLoadMore={onLoadMore}
            totalDocs={totalDocs}
          />
        )}
      </div>
    </div>
  )
}
